"use client"

import * as React from "react"
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs"

import { cn } from "@/lib/utils"

/*
 * Inset Dark Tabs — segmented selector with a single sliding pill that
 * animates between triggers (left/width interpolated). Each trigger stays
 * flat; the pill underneath carries the gradient + shadow stack.
 */

// Base UI className can be a state function; the wrappers feed it to cn(), so
// narrow it to a plain string (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

type TabsRootProps = TabsPrimitive.Root.Props & {
  /**
   * Accepted for showcase parity (`variant="underline"` is used by the
   * shadcn defaults). The inset-dark Tabs only ship one variant — the
   * sliding-pill segmented control — so this is consumed and ignored.
   */
  variant?: string
}

const Tabs = React.forwardRef<HTMLDivElement, TabsRootProps>(
  ({ variant: _variant, ...props }, ref) => (
    <TabsPrimitive.Root ref={ref} {...props} />
  )
)
Tabs.displayName = "Tabs"

const TabsList = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.List.Props>
>(({ className, children, ...props }, ref) => {
  const listRef = React.useRef<HTMLDivElement | null>(null)
  const pillRef = React.useRef<HTMLSpanElement | null>(null)
  const firstPaint = React.useRef(true)

  // SAFETY: the handle is read only after mount, when the element this
  // component renders is attached, so the ref is non-null.
  React.useImperativeHandle(ref, () => listRef.current as HTMLDivElement)

  React.useLayoutEffect(() => {
    const track = listRef.current
    const pill = pillRef.current
    if (!track || !pill) return

    const measure = () => {
      const active = track.querySelector<HTMLElement>("[data-active]")
      if (!active) {
        pill.style.opacity = "0"
        return
      }
      const trackRect = track.getBoundingClientRect()
      const r = active.getBoundingClientRect()
      // A scaled preview (transform: scale) shrinks the rects; undo it so the pill fits the tab.
      const s = trackRect.width / track.offsetWidth || 1
      pill.style.opacity = "1"
      pill.style.left = `${(r.left - trackRect.left) / s}px`
      pill.style.width = `${r.width / s}px`
    }

    if (firstPaint.current) {
      const prev = pill.style.transition
      pill.style.transition = "none"
      measure()
      void pill.offsetWidth
      pill.style.transition = prev
      firstPaint.current = false
    } else {
      measure()
    }

    const mo = new MutationObserver(measure)
    mo.observe(track, { subtree: true, attributes: true, attributeFilter: ["data-active"] })
    const ro = new ResizeObserver(measure)
    ro.observe(track)
    track.querySelectorAll<HTMLElement>('[role="tab"]').forEach((el) => ro.observe(el))

    window.addEventListener("resize", measure)
    return () => {
      mo.disconnect()
      ro.disconnect()
      window.removeEventListener("resize", measure)
    }
  }, [])

  return (
    <TabsPrimitive.List
      ref={listRef}
      className={cn(
        "relative inline-flex h-[2.625rem] items-center justify-center rounded-[0.75rem] p-1",
        "bg-card text-muted-foreground",
        "[box-shadow:var(--shadow-inset)]",
        className,
      )}
      {...props}
    >
      <span
        ref={pillRef}
        aria-hidden
        className={cn(
          "pointer-events-none absolute top-1 bottom-1 z-0 rounded-[0.5625rem]",
          "[background:var(--pill-gradient)]",
          "[box-shadow:var(--shadow-pill)]",
          "transition-[left,width,opacity] duration-[380ms]",
          "[transition-timing-function:cubic-bezier(0.32,0.72,0.28,1)]",
        )}
        style={{ opacity: 0 }}
      />
      {children}
    </TabsPrimitive.List>
  )
})
TabsList.displayName = "TabsList"

const TabsTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TabsPrimitive.Tab.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Tab
    ref={ref}
    className={cn(
      "relative z-10 inline-flex items-center justify-center whitespace-nowrap",
      "rounded-[0.5625rem] px-3.5 h-[2.125rem] text-sm font-medium tracking-[-0.01em]",
      "transition-[color] duration-fast",
      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40",
      "disabled:pointer-events-none disabled:opacity-50",
      "aria-disabled:pointer-events-none aria-disabled:opacity-50",
      "text-[oklch(1_0_0/0.55)] hover:text-[oklch(1_0_0/0.8)]",
      "data-active:text-foreground",
      "data-active:[text-shadow:var(--text-shadow-pressed)]",
      className,
    )}
    {...props}
  />
))
TabsTrigger.displayName = "TabsTrigger"

const TabsContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.Panel.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Panel
    ref={ref}
    className={cn(
      "mt-3 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40",
      className,
    )}
    {...props}
  />
))
TabsContent.displayName = "TabsContent"

export { Tabs, TabsList, TabsTrigger, TabsContent }
